{"explanation":"Uses separate permanent records for receives, sends, and spends, so namespaces and historical conflicts remain isolated. Successful sends debit immediately and remain pending until acknowledgment or one-time cancellation refund. Receive duplicates require the original grant amount; mismatches are invalid. Outputs rebuild sorted identifier arrays after each event.","program":"function solve({config,state,event}) {
  const positive=x=>typeof x==='number'&&Number.isSafeInteger(x)&&x>0;
  const idok=x=>typeof x==='string';
  const find=(a,id)=>a.findIndex(x=>x[0]===id);
  const has=(o,k)=>Object.keys(o).includes(k);
  const sort=a=>a.slice().sort((x,y)=>x<y?-1:x>y?1:0);
  if(state===null) state={a:config.initial,s:0,g:config.grants,r:[],w:[],d:[],p:[]};
  const e=event&&typeof event==='object'?event:{}, t=e.type, id=e.id, amt=e.amount;
  let status='ignored', i;
  if(t==='receive') {
    if(!idok(id)||!positive(amt)) status='invalid';
    else {
      i=find(state.r,id);
      if(i>=0) status=state.r[i][1]===amt?'duplicate':'invalid';
      else if(!has(state.g,id)||state.g[id]!==amt) status='invalid';
      else { state.r.push([id,amt]); state.a+=amt; status='accepted'; }
    }
  } else if(t==='send'||t==='spend') {
    const m=t==='send'?state.w:state.d;
    if(!idok(id)||!positive(amt)) status='invalid';
    else {
      i=find(m,id);
      if(i>=0) status=m[i][1]===amt?'duplicate':'conflict';
      else if(state.a<amt) status='insufficient';
      else { m.push([id,amt]); state.a-=amt; if(t==='send')state.p.push([id,amt]); else state.s+=amt; status='accepted'; }
    }
  } else if(t==='ack'||t==='cancel') {
    if(idok(id)) {
      i=find(state.p,id);
      if(i>=0) { if(t==='cancel')state.a+=state.p[i][1]; state.p.splice(i,1); status='accepted'; }
    }
  } else status='invalid';
  return {state:state,output:{status:status,available:state.a,spent:state.s,pending:sort(state.p.map(x=>x[0])),received:sort(state.r.map(x=>x[0]))}};
}"}
